sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }


	/*
	Eligibility Check Artifacts: 
	Script Include : x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
	System Property: x_hsb11_mss_c_proc.enableautomatedamend.market - Only available markets will allow this script to execute
	System Property: x_hsb11_mss_c_proc.enableautomatedamend.outcomes - Only available markets will allow this script to execute
	*/

    var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
    eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
    eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
	eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
    eligbleCheck.getXMLAnswer(handleEligiblity);

    function handleEligiblity(check) {
        //g_form.addInfoMessage('Eligible ' + check);
        if (check.toString() == 'true') {

            g_from.addInfoMessage('Within Loop');

			var trdSettlementCurr = g_scratchpad.settlementCurrency;
			var trdSettlementDate = g_scratchpad.settlementDate;
			var tskAmendDate = g_form.getValue("bulk_id.amend_trade_date");
			var amendCurr = g_form.getValue("bulk_id.amend_settlement_currency");
			var amendSettAmt = g_form.getValue("bulk_id.amend_settlement_amount");
			//var amendSettCurrency = g_form.getValue("bulk_id.amend_settlement_currency");
			var amendLocationCode = g_form.getValue("bulk_id.amend_location_code");
			var tradeId = g_form.getValue("trade_id");
			var gdiIndicator = g_form.getValue("bulk_id.amend_gdi_indicator");
			var placeOfSettlementBic = g_form.getValue("bulk_id.amend_place_of_settlement_bic");
			var amendScriptHoldIndicator = g_form.getValue("bulk_id.amend_script_hold_indicator");
			var amendSellerBuyerBic = g_form.getValue("bulk_id.amend_seller_bic_buyer_bic");
			var amendDealPrice = g_form.getValue("bulk_id.amend_deal_price");
			var amendDealCurrency = g_form.getValue("bulk_id.amend_deal_currency");
			var trdCashAccId = g_form.getValue("trade_id.cash_account_id");
			var amendBuyerSellerBic = g_form.getValue("bulk_id.amend_seller_bic_buyer_bic");
			var amendCustomerReference = g_form.getValue("bulk_id.customer_reference");
			var amendCashHoldIndicator = g_form.getValue("bulk_id.amend_cash_hold_indicator");
			var amendSuspenseAccNum = g_form.getValue("bulk_id.amend_suspense_account_number");

            // if ((g_form.getValue('outcome') == "Amend Trade") && (g_form.getValue('validate_amend_fields').toString() == "true")) { //Check if Maker or Checker

                var trdDetails = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
				trdDetails.addParam('sysparm_name', 'evalAmendInputs');
				trdDetails.addParam('sysparm_trdSettlementDate', trdSettlementDate);
				trdDetails.addParam('sysparm_taskAmendDate', tskAmendDate);
				trdDetails.addParam('sysparm_trdSettlementCurr', trdSettlementCurr);
				trdDetails.addParam('sysparm_taskAmendCurr', amendCurr);
				trdDetails.addParam('sysparm_taskAmendSettAmt', amendSettAmt);
				//trdDetails.addParam('sysparm_amendSettCurrency', amendSettCurrency);
				trdDetails.addParam('sysparm_taskAmendLocationCode', amendLocationCode);
				trdDetails.addParam('sysparm_tradeId', tradeId);
				trdDetails.addParam('sysparm_gdiIndicator', gdiIndicator);
				trdDetails.addParam('sysparm_placeOfSettlementBic', placeOfSettlementBic);
				trdDetails.addParam('sysparm_amendScriptHoldIndicator', amendScriptHoldIndicator);
				trdDetails.addParam('sysparm_amendSellerBuyerBic', amendSellerBuyerBic);
				trdDetails.addParam('sysparm_amendDealPrice', amendDealPrice);
				trdDetails.addParam('sysparm_amendDealCurrency', amendDealCurrency);
				trdDetails.addParam('sysparm_trdCashAccId', trdCashAccId);
				trdDetails.addParam('sysparm_amendBuyerSellerBic', amendBuyerSellerBic);
				trdDetails.addParam('sysparm_amendCustomerReference', amendCustomerReference);
				trdDetails.addParam('sysparm_amendCashHoldIndicator', amendCashHoldIndicator);
				trdDetails.addParam('sysparm_amendSuspenseAccNum', amendSuspenseAccNum);

                trdDetails.getXMLAnswer(handleResponse);
            }
        } 

    }

    function handleResponse(response) {

        if (response.length > 98) { //to limit if there are any warnings
            g_form.setValue('validate_amend_fields', false);
            g_form.addErrorMessage(response);

        }

    }
